public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i - 1, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (k >= nums[i - 1]) {
                    dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - nums[i - 1]];
                } else {
                    dp[i][j][k] = dp[i - 1][j][k];
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if (sum * j % n == 0 && dp[n][j][sum * j / n]) {
            return true;
        }
    }

    return false;
}

