public boolean hasAllCodes(String s, int k) {
    int need = 1 << k;
    boolean[] seen = new boolean[need];
    int allOne = need - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal & allOne) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1 && !seen[hashVal]) {
            seen[hashVal] = true;
            need--;
        }
    }
    return need == 0;
}

