public int minInsertions(String s) {
    int left = 0; // Count of '('
    int right = 0; // Count of ')' needed
    int insertions = 0; // Number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right > 0) {
                // We have extra ')' needed, but found a '('
                insertions += right; // Insert right ')' to balance
                if (right % 2 == 1) {
                    insertions++; // Need one more ')' to balance an odd right
                }
                right = 0; // Reset right count
            }
            left++;
        } else {
            right++; // We found a ')', increment needed right count
            if (right == 2) {
                // We found two ')', it can balance one '('
                if (left > 0) {
                    left--; // Balance with one '('
                } else {
                    insertions++; // No '(' to balance, insert one '('
                }
                right = 0; // Reset right count
            }
        }
    }

    // After the loop, we might still have unmatched '(' or ')' needed
    if (left > 0) {
        insertions += left * 2; // Each '(' needs two ')' to balance
    } else if (right > 0) {
        insertions += right; // Add remaining ')' needed
        if (right % 2 == 1) {
            insertions++; // Need one more ')' to balance an odd right
        }
    }

    return insertions;
}

