public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0) result.add(0);
    for (int i = 1; i <= 9; i++) {
        if (i >= low) {
            result.add(i);
        }
        findSteppingNumbersUtil(i, low, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersUtil(int num, int low, int high, List<Integer> result) {
    if (num > high) return;
    if (num >= low) result.add(num);
    int lastDigit = num % 10;
    int next1 = num * 10 + (lastDigit - 1);
    int next2 = num * 10 + (lastDigit + 1);
    if (lastDigit > 0) findSteppingNumbersUtil(next1, low, high, result);
    if (lastDigit < 9) findSteppingNumbersUtil(next2, low, high, result);
}

