public static int squarePermutations(int[] A) {
    boolean[] used = new boolean[A.length];
    List<Integer> path = new ArrayList<>();
    int[] count = new int[1];
    backtrack(A, used, path, count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> path, int[] count) {
    if (path.size() == A.length) {
        count[0]++;
        return;
    }

    Set<Integer> seen = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (path.size() > 0 && seen.contains(A[i])) || (path.size() > 0 && !isPerfectSquare(path.get(path.size() - 1) + A[i]))) {
            continue;
        }

        used[i] = true;
        path.add(A[i]);
        seen.add(A[i]);
        backtrack(A, used, path, count);
        used[i] = false;
        path.remove(path.size() - 1);
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
