    int[] left = new int[n];
    int[] right = new int[n];

    left[0] = -1;
    right[n - 1] = n;

    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) {
            p = left[p];
        }
        left[i] = p;
    }

    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) {
